import{_ as s,o as e,c as t,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Shell 基础","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/shell-basics.md","filePath":"zh/manual/shell-basics.md"}'),l={name:"zh/manual/shell-basics.md"};function p(i,a,o,c,d,h){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="shell-基础" tabindex="-1">Shell 基础 <a class="header-anchor" href="#shell-基础" aria-label="Permalink to &quot;Shell 基础&quot;">​</a></h1><p><code>ush</code> 是启动 shell——一个真正的 ring-3 程序（唯一的 <code>OC_L1_APP_DECL</code> 应用），作为整个系统的前端。</p><h2 id="提示符" tabindex="-1">提示符 <a class="header-anchor" href="#提示符" aria-label="Permalink to &quot;提示符&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt;</span></span></code></pre></div><h2 id="运行程序" tabindex="-1">运行程序 <a class="header-anchor" href="#运行程序" aria-label="Permalink to &quot;运行程序&quot;">​</a></h2><p>输入注册表程序名（共有 284 个——<code>help -a</code> 会全部列出）。8 个大应用是预期的操作面；历史单命令也继续可用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; hwinfo</span></span>
<span class="line"><span>ush&gt; lsblk</span></span>
<span class="line"><span>ush&gt; run hello &amp;            (the &#39;&amp;&#39; suffix runs in background)</span></span></code></pre></div><p><code>run &lt;program&gt;</code> 是显式形式——它会打印所启动的 pid 并等待（或加 <code>&amp;</code> 转入后台）。</p><h2 id="管道与重定向" tabindex="-1">管道与重定向 <a class="header-anchor" href="#管道与重定向" aria-label="Permalink to &quot;管道与重定向&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; cat /etc/opencube.conf | grep url</span></span>
<span class="line"><span>ush&gt; help -a &gt; registry.txt</span></span>
<span class="line"><span>ush&gt; echo hello &gt;&gt; notes.txt</span></span>
<span class="line"><span>ush&gt; wc &lt; notes.txt</span></span></code></pre></div><p>管道（<code>|</code>）、截断重定向（<code>&gt;</code>）、追加重定向（<code>&gt;&gt;</code>）与输入重定向（<code>&lt;</code>）在所有注册表程序间通用。</p><h2 id="内置命令与程序" tabindex="-1">内置命令与程序 <a class="header-anchor" href="#内置命令与程序" aria-label="Permalink to &quot;内置命令与程序&quot;">​</a></h2><p>只有进程状态类命令内置于 ush：<code>cd</code>、<code>pwd</code>、<code>exit</code>、<code>help</code>、<code>export</code>、<code>alias</code>、<code>unalias</code>、<code>history</code>、<code>lang</code>、<code>clear</code>。其余一切——包括 <code>ls</code>、<code>cat</code>、<code>echo</code>、<code>write</code>——都是经 fork 运行的注册表程序。这正是 <code>ls</code> 在管道中以真实进程出现的原因。</p><p>行编辑器：上/下方向键翻阅历史，Tab 补全程序名，Ctrl+C 取消当前行。</p><h2 id="别名与环境变量" tabindex="-1">别名与环境变量 <a class="header-anchor" href="#别名与环境变量" aria-label="Permalink to &quot;别名与环境变量&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; alias dt disk-tool</span></span>
<span class="line"><span>ush&gt; alias</span></span>
<span class="line"><span>ush&gt; unalias dt</span></span>
<span class="line"><span>ush&gt; export EDITOR=edit</span></span></code></pre></div><h2 id="脚本" tabindex="-1">脚本 <a class="header-anchor" href="#脚本" aria-label="Permalink to &quot;脚本&quot;">​</a></h2><p>用 <code>;</code> 串联多条命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dhcp; ping 10.0.2.2; dns example.com</span></span></code></pre></div><p>本版本没有基于文件的脚本解释器——&quot;脚本&quot;指的是粘贴进去的一串命令行，或你在构建期写入注册表的程序（见开发者文档）。</p><h2 id="语言" tabindex="-1">语言 <a class="header-anchor" href="#语言" aria-label="Permalink to &quot;语言&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lang zh        (the whole UI - shell help + every wizard -</span></span>
<span class="line"><span>                     switches to Chinese live)</span></span>
<span class="line"><span>ush&gt; lang           (shows the current language)</span></span></code></pre></div><h2 id="大应用契约-回顾" tabindex="-1">大应用契约（回顾） <a class="header-anchor" href="#大应用契约-回顾" aria-label="Permalink to &quot;大应用契约（回顾）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; &lt;app&gt;                wizard (menus, single-key picks, q quits)</span></span>
<span class="line"><span>ush&gt; &lt;app&gt; direct &lt;op&gt;    explicit verbatim passthrough</span></span>
<span class="line"><span>ush&gt; &lt;app&gt; &lt;op&gt; [args]    classic dispatch (historical spelling)</span></span></code></pre></div><p>完整契约与逐应用详解见 <a href="./mega-apps.html">mega-apps</a>。</p>`,25)])])}const g=s(l,[["render",p]]);export{u as __pageData,g as default};
